# region: digest
def digest(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
            return out
    return out

# region: fold
def fold(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: emit
def emit(xs):
    return [v for v in xs if v % 2 == 0]

# region: render
def render(xs, factor=3):
    return [v * factor for v in xs]

# region: intake
def intake(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: gather
def gather(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return gather(intake(render(emit(fold(digest(raw))))))

